 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_keywrdNm_onkeydown = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_keywrdNm_onkeydown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.searchKey();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70040.ipt_keywrdNm_onkeydown' }); }
};

