///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_searchKeywrdListDtl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchKeywrdListDtl = async function () {
    const sbmOptions = {
        id: "tx_fn_searchKeywrdListDtl",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_searchKeywrdListDtlReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf70040.tx_fn_searchKeywrdListDtl" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchKey
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchKey = function () {
    /* sdd-asis-lifecycle:begin fn_searchKey — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        scwin.fn_searchKeywrdListDtl();
        $('.sort a').removeClass('active');
        (($c.util.getComponent('all')) && ($c.util.getComponent('all')).addClass ? ($c.util.getComponent('all')).addClass('active') : console.error('[sdd] addClass 미지원 컴포넌트: all'));
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.moveKeywrdList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.moveKeywrdList = function () {
    /* sdd-asis-lifecycle:begin fn_moveKeywrdList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.fn_searchKeywrdListDtl("", true);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setParetKeywrd
 * @author Inswave
 * @date 2026. 09. 29
 * @param keywrd
 * @returns
 * @hidden N
*/
scwin.setParetKeywrd = function (keywrd) {
    /* sdd-asis-lifecycle:begin fn_SetParetKeywrd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.getParent().fn_SetKeywrd(keywrd);
    $c.frame.CloseFrame();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.clickKeyword
 * @author Inswave
 * @date 2026. 09. 29
 * @param ele
 * @returns
 * @hidden N
*/
scwin.clickKeyword = function (ele) {
    /* sdd-asis-lifecycle:begin clickKeyword — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('.sort a').on('click', function() {
            if ($(this).hasClass('active')) {
                return false;
            }
            $('.sort a').removeClass('active');
            $(this).addClass('active');
    });
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_searchKeywrdListDtl = scwin.tx_fn_searchKeywrdListDtl;
